type ElementProps<Options, Handle> = Options & {
	/** The element's live handle (same surface as the vanilla `create` return). */
	ref?: Ref<Handle>;
	/** Applied to the element's mount container (the wrapper this component renders; the element itself lives in its own frame, see the Styling docs for restyling it). */
	className?: string;
	/** Applied to the element's mount container (the wrapper this component renders). */
	style?: CSSProperties;
	/** Shown until the element is fully loaded. When omitted, the element's own internal loading UI is shown instead. */
	fallback?: ReactNode;
};

/**
 * Drives an account's money surfaces. `actions` renders the Deposit, Accept, Send, and Convert controls: Deposit, Send, and Convert open their Wallet overlays, while Accept opens Whop's checkout-link creator for a business account or company creation for a personal account. `deposit` returns live funding rails; `convert` swaps USD with Gold or Bitcoin and exposes FX currencies when the host enables `fxEnabled`; `send` moves money to a recipient or creates a public claim link; `withdraw` lists payout methods and creates the payout when the host does not already drive that API; `balances` holds two faces — the holdings list, and the balance block drawing value over a window; `cards` is the compact issued-card list; `cardsTable` renders the full sortable card roster; `cardsChart` plots card spend; `whopCard` renders one revealable card; `activity` lists ledger movements; `activityDetail` renders a prefetched movement, or retrieves one by activity ID or card transaction ID, in a standalone drawer. The outstanding-action bar and the identity nudge live on the `dashboard` controller. Every data-backed surface can use the viewer's session when no token is provided.
 * Provider component: creates the WalletHandle and drives the element components rendered as children. `fallback` shows until every child element has loaded (grouped); `ref` exposes the live handle. Unmounting it destroys the handle and everything it created.
 * @example
 * ```tsx
 * import { WhopElements, Wallet, ActionsElement, ActivityElement, ActivityDetailElement, DepositElement, ConvertElement, WithdrawElement, SendElement, CardDetailsElement } from "@whop/elements-react";
 * import { loadWhop } from "@whop/elements";
 * 
 * function Example() {
 *   return (
 *     <WhopElements elements={loadWhop()}>
 *       <Wallet>
 *         <ActionsElement />
 *         <ActivityElement />
 *         <ActivityDetailElement />
 *         <DepositElement />
 *         <ConvertElement />
 *         <WithdrawElement />
 *         <SendElement />
 *         <CardDetailsElement />
 *       </Wallet>
 *     </WhopElements>
 *   );
 * }
 * ```
 * @see https://docs.whop.com/elements/latest/wallet/overview
 */
export declare function Wallet(
	props: WalletOptions & { children?: ReactNode; fallback?: ReactNode; ref?: Ref<{ handle: WalletHandle | null }> },
): ReactNode;
/**
 * The nearest `<Wallet>` ancestor's live handle, `null` until it boots. Must be called under a `<Wallet>`.
 * @see https://docs.whop.com/elements/latest/wallet/overview
 */
export declare function useWallet(): WalletHandle | null;

/**
 * The account action row from Whop's balance dashboard. Deposit, Send, Withdraw, and Convert open the Wallet controller's built-in overlays. Accept opens Whop's checkout-link creator for a business account or company creation for a personal account. Each button also emits its requested event so the embedding page can observe the action.
 * @example
 * ```tsx
 * import { WhopElements, Wallet, ActionsElement } from "@whop/elements-react";
 * import { loadWhop } from "@whop/elements";
 * 
 * function Example() {
 *   return (
 *     <WhopElements elements={loadWhop()}>
 *       <Wallet>
 *         <ActionsElement />
 *       </Wallet>
 *     </WhopElements>
 *   );
 * }
 * ```
 * @see https://docs.whop.com/elements/latest/wallet/actions
 */
export declare function ActionsElement(props: ElementProps<ActionsElementCreateOptions, ActionsElementHandle>): ReactNode;
